--[[
    KLZE HUB Universal Loader
    Jnkie key gate + hub API script load
    Logs errors to workspace/hub_debug.txt
]]

local function klzePrepareReload()
    local g = typeof(getgenv) == "function" and getgenv() or _G
    if type(g.KLZE_DTEC_UNLOAD) == "function" then
        pcall(g.KLZE_DTEC_UNLOAD)
    end
    if type(g.KLZE_PYRAMID_UNLOAD) == "function" then
        pcall(g.KLZE_PYRAMID_UNLOAD)
    elseif type(g.KLZE_PYRAMID_CLEANUP) == "function" then
        pcall(g.KLZE_PYRAMID_CLEANUP)
    end
    local lib = g.KLZE_OBSIDIAN_LIBRARY
    if lib and lib.Unloaded ~= true then
        pcall(function()
            if type(lib.UnloadSignals) == "table" then
                table.clear(lib.UnloadSignals)
            end
            if type(lib.Unload) == "function" then
                lib:Unload()
            end
        end)
    end
    g.KLZE_OBSIDIAN_READY = nil
    g.KLZE_OBSIDIAN_LIBRARY = nil
    g.KLZE_OBSIDIAN_SAVE = nil
    g.KLZE_OBSIDIAN_THEME = nil
    g.KLZE_HUB_WINDOW = nil
    g.__KLZE_LOADER_RUNNING = nil
    g.__KLZE_GAME_SCRIPT_LOADED = nil
    g.__KLZE_PRESENCE_LOOP = nil
end

