        if ok and type(id) == "string" and id ~= "" then
            return id
        end
    end
    local lp = Players.LocalPlayer
    return lp and tostring(lp.UserId) or "unknown"
end

local function getExecutorLabel()
    if typeof(identifyexecutor) == "function" then
        local ok, name = pcall(identifyexecutor)
        if ok and type(name) == "string" and name ~= "" then
            return name
        end
    end
    return "Unknown"
end

local function heartbeatApiBase()
    -- Worker only. Pages has no D1; pinging pages.dev never shows in admin Live.
    if type(HEARTBEAT_API) == "string" and HEARTBEAT_API ~= "" then
        return HEARTBEAT_API:gsub("/+$", "")
    end
    if typeof(getgenv) == "function" and type(getgenv().KLZE_HEARTBEAT_URL) == "string" then
        local override = getgenv().KLZE_HEARTBEAT_URL:gsub("/+$", "")
        if override ~= "" then
            return override
        end
    end
    return "https://hub-script-api.guicolucce1.workers.dev"
end

local function collectHttpRequestFns()
    local list = {}
    local seen = {}
    local function add(fn)
        if type(fn) == "function" and not seen[fn] then
            seen[fn] = true
            table.insert(list, fn)
        end
    end
    pcall(function()
        if syn then
            add(syn.request)
            add(syn.http_request)
        end
    end)
    pcall(function()
        add(http_request)
    end)
    pcall(function()
        add(request)
    end)
    pcall(function()
        if http then
            add(http.request)
        end
    end)
    pcall(function()
        if fluxus then
            add(fluxus.request)
        end
    end)
    pcall(function()
        if krnl then
            add(krnl.request)
        end
    end)
    pcall(function()
        add(httprequest)
    end)
    pcall(function()
        if typeof(getgenv) == "function" then
            local g = getgenv()
            add(g.http_request)
            add(g.request)
            add(g.httprequest)
            if type(g.http) == "table" then
                add(g.http.request)
            end
        end
    end)
    return list
end

local function heartbeatAccepted(res)
    local body = res
    if type(res) == "table" then
        local code = res.StatusCode or res.Status or res.status_code or res.statusCode
        if type(code) == "number" and (code < 200 or code >= 300) then
            return false
        end
        body = res.Body or res.body or res.Data or res.data
    end
    return type(body) == "string" and (string.find(body, '"stored"%s*:%s*true') or string.find(body, '"ok"%s*:%s*true'))
end

local function fireHeartbeatGet(url)
    local headers = { Accept = "application/json" }
    for _, fn in ipairs(collectHttpRequestFns()) do
        local ok, res = pcall(fn, { Url = url, Method = "GET", Headers = headers })
        if ok and heartbeatAccepted(res) then
            return true
        end
        ok, res = pcall(fn, { url = url, method = "GET", headers = headers })
        if ok and heartbeatAccepted(res) then
            return true
        end
    end
    if type(game.HttpGet) == "function" then
        local ok, body = pcall(function()
            return game:HttpGet(url, true)
        end)
        if ok and heartbeatAccepted(body) then
            return true
        end
    end
    if type(game.HttpGetAsync) == "function" then
        local ok, body = pcall(function()
            return game:HttpGetAsync(url)
        end)
        if ok and heartbeatAccepted(body) then
            return true
        end
    end
    return false
end

local function sendLoaderHeartbeat(placeName, opts)
    opts = type(opts) == "table" and opts or {}
    local ok, err = pcall(function()
        local lp = Players.LocalPlayer
        if not lp then
            return
        end
        local name = placeName
        if type(name) ~= "string" or name == "" or name == "Unknown" then
            pcall(function()
                name = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name
            end)
        end
        local fields = {
            robloxUserId = tostring(lp.UserId),
            robloxName = lp.Name,
            displayName = lp.DisplayName,
            placeId = tostring(game.PlaceId),
            universeId = tostring(game.GameId),
            placeName = name or "Unknown",
            executor = getExecutorLabel(),
            hwid = loaderHwid(),
            loaderVersion = LOADER_PRESENCE_VERSION,
        }
        local parts = {}
        for key, value in pairs(fields) do
            table.insert(parts, key .. "=" .. HttpService:UrlEncode(tostring(value or "")))
        end
        if opts.offline then
            table.insert(parts, "offline=1")
        end
        if opts.fresh then
            table.insert(parts, "fresh=1")
        end
        local getUrl = heartbeatApiBase() .. "/heartbeat?" .. table.concat(parts, "&")
        if opts.offline then
            fireHeartbeatGet(getUrl)
            return
        end
        if fireHeartbeatGet(getUrl) then
            print("[KLZE HUB] Heartbeat stored")
            return
        end
        print("[KLZE HUB] Heartbeat fail: ping did not reach admin")
    end)
    if not ok then
        print("[KLZE HUB] Heartbeat error: " .. tostring(err))
    end
end

local presenceLeft = false
local function sendLoaderLeave()
    if presenceLeft then
        return
    end
    presenceLeft = true
    sendLoaderHeartbeat(nil, { offline = true })
end

local function startLoaderPresence(placeName)
    if typeof(getgenv) == "function" and getgenv().__KLZE_PRESENCE_LOOP then
        return
    end
    if typeof(getgenv) == "function" then
        getgenv().__KLZE_PRESENCE_LOOP = true
    end
    presenceLeft = false
    task.spawn(function()
        if not Players.LocalPlayer then
            Players.PlayerAdded:Wait()
        end
        sendLoaderHeartbeat(placeName, { fresh = true })
        while not presenceLeft do
            task.wait(HEARTBEAT_INTERVAL)
            if presenceLeft then
                break
            end
            sendLoaderHeartbeat(placeName)
        end
    end)
    Players.PlayerRemoving:Connect(function(player)
        if player == Players.LocalPlayer then
            sendLoaderLeave()
        end
    end)
    pcall(function()
        game:GetService("GuiService").NativeClose:Connect(sendLoaderLeave)
    end)
end

local function log(line)
    local text = os.date("%H:%M:%S") .. " | " .. tostring(line)
    print("[KLZE HUB]", line)
    if typeof(appendfile) == "function" then
        pcall(appendfile, LOG_FILE, text .. "\n")
    elseif typeof(writefile) == "function" then
        local prev = ""
        if typeof(readfile) == "function" and typeof(isfile) == "function" and isfile(LOG_FILE) then
            local okRead, data = pcall(readfile, LOG_FILE)
            if okRead and type(data) == "string" then
                prev = data
            end
        end
        pcall(writefile, LOG_FILE, prev .. text .. "\n")
    end
end

local function logError(label, err)
    log("ERROR [" .. label .. "]: " .. tostring(err))
    if debug and debug.traceback then
        log(debug.traceback(tostring(err), 2))
    end
end

local function notify(title, text, duration)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {
            Title = title,
            Text = text,
            Duration = duration or 5,
        })
    end)
end

local function trim(text)
    return (tostring(text or "")):gsub("^%s+", ""):gsub("%s+$", "")
end

local function stripBom(source)
    if type(source) ~= "string" then
        return source
    end
    if source:sub(1, 3) == "\239\187\191" then
        return source:sub(4)
    end
    return source
end

local function runSource(source, chunkName)
    source = stripBom(source)
    chunkName = chunkName or "KLZEHub"

    if typeof(compile) == "function" then
        local ok, result = pcall(function()
            return compile(source, chunkName)()
        end)
        if ok then
            return result
        end
    end

    if typeof(loadstring) ~= "function" then
        error("Executor missing loadstring()")
    end

    local fn, err = loadstring(source, chunkName)
    if not fn then
        error(tostring(err))
    end

    if setfenv and typeof(getgenv) == "function" then
        setfenv(fn, getgenv())
    end

    return fn()
end

local function copyToClipboard(text)
    if typeof(setclipboard) == "function" then
        setclipboard(text)
        return true
    end
    if typeof(toclipboard) == "function" then
        toclipboard(text)
        return true
    end
    if syn and typeof(syn.write_clipboard) == "function" then
        syn.write_clipboard(text)
        return true
    end
    return false
end

local function getGuiParent()
    local playerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
    if typeof(gethui) == "function" then
        return gethui()
    end
    return playerGui
end

local function loadSavedJnkieKey()
    if typeof(readfile) ~= "function" then
        return nil
    end
    local ok, data = pcall(readfile, JNKIE_KEY_FILE)
    if ok and type(data) == "string" then
        local key = trim(data)
        if #key > 0 then
            return key
        end
    end
    return nil
end

local function saveJnkieKey(key)
    key = trim(key)
    if key == "" or typeof(writefile) ~= "function" then
        return false
    end
    local ok = pcall(writefile, JNKIE_KEY_FILE, key)
    return ok
end

local function clearSavedJnkieKey()
    if typeof(delfile) == "function" and typeof(isfile) == "function" and isfile(JNKIE_KEY_FILE) then
        pcall(delfile, JNKIE_KEY_FILE)
    end
end

local function setGlobalScriptKey(key)
    if typeof(getgenv) == "function" then
        getgenv().SCRIPT_KEY = key
    end
    if typeof(getrenv) == "function" then
        pcall(function()
            getrenv().SCRIPT_KEY = key
        end)
    end
end

local function loadJnkieSdk()
    if JNKIE_IDENTIFIER == "CHANGE_ME" or JNKIE_IDENTIFIER == "" then
        return nil, "Set JNKIE_IDENTIFIER in loader.lua (your Jnkie user ID)"
    end

    if typeof(loadstring) ~= "function" then
        return nil, "Executor missing loadstring()"
    end

    local ok, Junkie = pcall(function()
        local body = game:HttpGet(JNKIE_SDK_URL, true)
        if type(body) ~= "string" or #body < 16 then
            error("Jnkie SDK response empty")
        end
        return runSource(body, "JnkieSDK")
    end)

    if not ok then
        return nil, "Jnkie SDK failed (executor may not support it): " .. tostring(Junkie)
    end

    if type(Junkie) ~= "table" then
        return nil, "Jnkie SDK returned invalid data"
    end

    if type(Junkie.check_key) ~= "function" then
        return nil, "Jnkie SDK missing check_key()"
    end

    Junkie.service = JNKIE_SERVICE
    Junkie.identifier = JNKIE_IDENTIFIER
    Junkie.provider = JNKIE_PROVIDER

    return Junkie
end

local function isJnkieValidationOk(validation)
    return type(validation) == "table" and (validation.valid == true or validation.success == true)
end

