local function tryJnkieKeyless(Junkie)
    if not Junkie then
        return false
    end
    local ok = select(1, validateJnkieKey(Junkie, "KEYLESS"))
    return ok == true
end

local function createLoaderGui(minimal)
    minimal = minimal == true
    local parent = getGuiParent()

    local existing = parent:FindFirstChild("KLZEHubLoader")
    if existing then
        existing:Destroy()
    end

    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "KLZEHubLoader"
    screenGui.ResetOnSpawn = false
    screenGui.IgnoreGuiInset = true
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    screenGui.DisplayOrder = 9999

    if syn and typeof(syn.protect_gui) == "function" then
        syn.protect_gui(screenGui)
    end

    local root = Instance.new("Frame")
    root.Name = "Root"
    root.AnchorPoint = Vector2.new(0.5, 0.5)
    root.Position = UDim2.new(0.5, 0, 0.44, 0)
    root.Size = minimal and UDim2.fromOffset(360, 118) or UDim2.fromOffset(400, 332)
    root.BackgroundColor3 = Color3.fromRGB(12, 12, 18)
    root.BorderSizePixel = 0
    root.ClipsDescendants = true
    root.Parent = screenGui

    local rootCorner = Instance.new("UICorner")
    rootCorner.CornerRadius = UDim.new(0, 16)
    rootCorner.Parent = root

