    end)

    local dragging = false
    local dragStart
    local startPos

    dragBar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = root.Position
        end
    end)

    local dragMoveConn = UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            local delta = input.Position - dragStart
            root.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y
            )
        end
    end)

    local dragEndConn = UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    local validateCallback

    local function setStatus(text, color)
        status.Text = text
        if color then
            status.TextColor3 = color
        end
    end

    local function setProgress(ratio)
        ratio = math.clamp(ratio or 0, 0, 1)
        TweenService:Create(progressFill, TweenInfo.new(0.35, Enum.EasingStyle.Quint), {
            Size = UDim2.new(math.max(ratio, 0.08), 0, 1, 0),
        }):Play()
    end

    local function setValidating(active)
        if not validateBtn or not keyInput then
            return
        end
        validateBtn.Text = active and "Validating..." or "Validate Key"
        validateBtn.BackgroundColor3 = active and Color3.fromRGB(90, 150, 120) or Color3.fromRGB(67, 181, 129)
        keyInput.TextEditable = not active
    end

    local function submitKey()
        if not keyInput or not validateCallback then
            return
        end
            validateCallback(trim(keyInput.Text))
    end

    if validateBtn then
    validateBtn.MouseButton1Click:Connect(submitKey)
    end

    if keyInput then
    keyInput.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            submitKey()
        end
    end)
    end

