    closeBtn.MouseButton1Click:Connect(function()
        if typeof(getgenv) == "function" then
            getgenv().KLZE_UI_CLOSED = true
        end
        TweenService:Create(root, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
            Position = root.Position + UDim2.fromOffset(0, 20),
            BackgroundTransparency = 1,
        }):Play()
        task.delay(0.32, function()
            dragMoveConn:Disconnect()
            dragEndConn:Disconnect()
            screenGui:Destroy()
        end)
    end)

    return {
        setStatus = setStatus,
        setProgress = setProgress,
        setKeyText = function(text)
            if keyInput then
            keyInput.Text = text or ""
            end
        end,
        getKeyText = function()
            if keyInput then
            return trim(keyInput.Text)
            end
            return ""
        end,
        setValidating = setValidating,
        onValidate = function(callback)
            validateCallback = callback
        end,
        close = function()
            if not screenGui.Parent then
                return
            end
            TweenService:Create(root, TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                Position = root.Position + UDim2.fromOffset(0, 16),
                BackgroundTransparency = 1,
            }):Play()
            TweenService:Create(rootStroke, TweenInfo.new(0.35, Enum.EasingStyle.Quint), { Transparency = 1 }):Play()
            TweenService:Create(title, TweenInfo.new(0.3, Enum.EasingStyle.Quint), { TextTransparency = 1 }):Play()
            TweenService:Create(subtitle, TweenInfo.new(0.3, Enum.EasingStyle.Quint), { TextTransparency = 1 }):Play()
            TweenService:Create(status, TweenInfo.new(0.3, Enum.EasingStyle.Quint), { TextTransparency = 1 }):Play()
            task.delay(0.38, function()
                dragMoveConn:Disconnect()
                dragEndConn:Disconnect()
                if screenGui.Parent then
                    screenGui:Destroy()
                end
            end)
        end,
        destroy = function()
            if screenGui.Parent then
                screenGui:Destroy()
            end
        end,
    }
end

local function getPresetJnkieKey()
    if typeof(getgenv) == "function" then
        local key = getgenv().SCRIPT_KEY
        if type(key) == "string" then
            key = trim(key)
            if #key > 0 then
                return key
            end
        end
    end
    return nil
end

