        if #res > 0 then
            return res, 200
        end
        return nil, nil, "empty string"
    end
    if type(res) ~= "table" then
        return nil, nil, "bad response type"
    end
    local code = res.StatusCode or res.Status or res.status_code or res.statusCode
    local body = res.Body or res.body or res.Data or res.data
    if type(body) ~= "string" or body == "" then
        return nil, code, "HTTP " .. tostring(code) .. " len=0"
    end
    local success = res.Success
    if success == nil then
        success = type(code) ~= "number" or (code >= 200 and code < 300)
    end
    if not success and type(code) == "number" and code == 0 and looksLikeHubScript(body) then
        return body, 200
    end
    if success or (type(code) == "number" and code >= 200 and code < 300) then
        return body, code or 200
    end
    return nil, code, "HTTP " .. tostring(code) .. " len=" .. tostring(#body) .. " " .. body:sub(1, 120)
end

local function httpGet(url)
    url = withScriptGate(url)
    local headers = klzeClientHeaders()
    local lastErr = "no http method worked"
    local HttpService = game:GetService("HttpService")
    pcall(function()
        log("HttpService.HttpEnabled: " .. tostring(HttpService.HttpEnabled))
    end)

    local payloads = {
        { Url = url, Method = "GET", Headers = headers },
        { url = url, method = "GET", headers = headers },
    }

    local function acceptBody(body, code, name)
        if type(body) ~= "string" or body == "" then
            return nil
        end
        if looksLikeHubScript(body) then
            log("HTTP ok via " .. name .. " (" .. tostring(code or 200) .. ", " .. #body .. " bytes)")
            return body, code or 200
        end
        if #body < 500 and body:sub(1, 2) == "--" then
            lastErr = name .. ": " .. body:sub(1, 120)
            log("HTTP try failed: " .. lastErr)
            return nil
        end
        lastErr = name .. ": unexpected body len=" .. tostring(#body)
        log("HTTP try failed: " .. lastErr)
        return nil
    end

    local fnIndex = 0
    for _, fn in ipairs(collectHttpRequestFns()) do
        fnIndex += 1
        for payloadIndex, payload in ipairs(payloads) do
            local label = "request#" .. fnIndex .. (payloadIndex == 2 and ":lower" or "")
            local ok, res = pcall(fn, payload)
            if not ok then
                lastErr = label .. ": " .. tostring(res)
                log("HTTP try failed: " .. lastErr)
            else
                local body, code, err = extractHttpBody(res)
                if body then
                    local accepted = acceptBody(body, code, label)
                    if accepted then
                        return accepted
                    end
                else
                    lastErr = label .. ": " .. tostring(err)
                    log("HTTP try failed: " .. lastErr)
                end
            end
        end
    end

    if type(HttpService.RequestAsync) == "function" then
        for payloadIndex, payload in ipairs(payloads) do
            local label = "HttpService:RequestAsync" .. (payloadIndex == 2 and ":lower" or "")
            local ok, res = pcall(function()
                return HttpService:RequestAsync({
                    Url = payload.Url or payload.url,
                    Method = "GET",
                    Headers = payload.Headers or payload.headers,
                })
            end)
            if ok then
                local body, code, err = extractHttpBody(res)
                if body then
                    local accepted = acceptBody(body, code, label)
                    if accepted then
                        return accepted
                    end
                else
                    lastErr = label .. ": " .. tostring(err)
                    log("HTTP try failed: " .. lastErr)
                end
            else
                lastErr = label .. ": " .. tostring(res)
                log("HTTP try failed: " .. lastErr)
            end
        end
    end

    if type(HttpService.GetAsync) == "function" then
        local ok, body = pcall(function()
            return HttpService:GetAsync(url)
        end)
        if ok then
            local accepted = acceptBody(body, 200, "HttpService:GetAsync")
            if accepted then
                return accepted
            end
        else
            lastErr = "HttpService:GetAsync: " .. tostring(body)
            log("HTTP try failed: " .. lastErr)
        end
    end

    if type(game.HttpGet) == "function" or type(game.HttpGetAsync) == "function" then
        local ok, body = pcall(function()
            if type(game.HttpGet) == "function" then
                return game:HttpGet(url, true)
            end
            return game:HttpGetAsync(url)
        end)
        if ok then
            local accepted = acceptBody(body, 200, "game:HttpGet")
            if accepted then
                return accepted
            end
        else
            lastErr = "HttpGet: " .. tostring(body)
            log("HTTP try failed: " .. lastErr)
        end
    end

    error(lastErr .. " | Enable HttpGet in Potassium/executor settings")
end

local function isApiError(body)
    if type(body) ~= "string" or body == "" then
        return true, "Empty API response"
    end
    if body == "Unauthorized" then return true, "Unauthorized" end
    local firstLine = body:match("^%s*(.-)\r?\n") or body
    if firstLine:sub(1, 2) ~= "--" then
        -- JSON/error pages usually aren't scripts
        if firstLine:sub(1, 1) == "{" or firstLine:lower():find("<!doctype", 1, true) or firstLine:lower():find("<html", 1, true) then
            return true, "API returned non-script: " .. firstLine:sub(1, 80)
        end
        return false
    end
    local lower = firstLine:lower()
    if lower:find("not supported", 1, true) then return true, "Game not supported yet" end
    if lower:find("disabled", 1, true) then return true, "Game disabled in manifest" end
    if lower:find("failed to load", 1, true) then return true, "API failed to load script" end
    return false
end

local function loadHubScript(gui)
    local HttpService = game:GetService("HttpService")
    local placeId = tostring(game.PlaceId)
    local gameName = "Unknown"

    pcall(function()
        gameName = game:GetService("MarketplaceService"):GetProductInfo(placeId).Name
    end)

    log("Game: " .. gameName)
    gui.setStatus("Loading " .. gameName .. "...", Color3.fromRGB(130, 200, 255))
    gui.setProgress(0.35)
    notify("KLZE HUB", "Loading " .. gameName .. " (" .. placeId .. ")", 4)

    local universeId = tostring(game.GameId)
    local url = string.format(
        "%s/script/%s?universeId=%s",
        API_URL,
        placeId,
        HttpService:UrlEncode(universeId)
    )
    log("Request: " .. url)
    log("UniverseId: " .. universeId)

    local ok, result, status = pcall(function()
        return httpGet(url)
    end)

    if not ok then
        local errText = tostring(result)
        logError("HTTP", errText)
        local hint = "API error - see hub_debug.txt"
        if errText:find("HTTP 0", 1, true) or errText:find("HttpGet", 1, true) then
            hint = "HTTP blocked: enable HttpGet / Allow HTTP in Potassium, rejoin, retry"
            log("Hint: Potassium -> Settings -> Allow HTTP / HttpGet ON, then re-run loader")
        end
        gui.setStatus(hint, Color3.fromRGB(255, 120, 120))
        notify("KLZE HUB", hint, 8)
        return false
    end

    log("HTTP status: " .. tostring(status))
    log("Response length: " .. tostring(#tostring(result)))
    gui.setProgress(0.65)
