¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â executing...", Color3.fromRGB(130, 200, 255))

    local isErr, errMsg = isApiError(result)
    if isErr then
        logError("API", errMsg)
        gui.setStatus(tostring(errMsg), Color3.fromRGB(255, 120, 120))
        notify("KLZE HUB", tostring(errMsg), 6)
        return false
    end

    if typeof(getgenv) == "function" then
        getgenv().KLZE_API_URL = API_URL
    end

    local execOk, execErr = pcall(function()
        log("Executing game script...")
        runSource(result, "KLZEHub_" .. placeId)
    end)

    if execOk then
        log("SUCCESS - script loaded")
        if typeof(getgenv) == "function" then
            getgenv().__KLZE_GAME_SCRIPT_LOADED = true
        end
        gui.setProgress(1)
        gui.setStatus("Script loaded successfully!", Color3.fromRGB(120, 220, 160))
        notify("KLZE HUB", "Script loaded!", 4)
        startLoaderPresence(gameName)
        task.delay(0.6, function()
            gui.close()
        end)
        return true
    end

    logError("Exec", execErr)
    gui.setStatus("Script error: " .. tostring(execErr):sub(1, 90), Color3.fromRGB(255, 120, 120))
    notify("KLZE HUB", "Script error - check hub_debug.txt", 6)
    return false
end

-- ========== BOOT ==========
if not game:IsLoaded() then
    game.Loaded:Wait()
end

if typeof(writefile) == "function" then
    pcall(writefile, LOG_FILE, "=== KLZE HUB DEBUG LOG ===\n")
end

if typeof(getgenv) == "function" then
    getgenv().KLZE_UI_CLOSED = false
end

local function noopGui()
    return {
        setStatus = function() end,
        setProgress = function() end,
        setKeyText = function() end,
        getKeyText = function() return "" end,
        setValidating = function() end,
        onValidate = function() end,
        close = function() end,
        destroy = function() end,
    }
end

log("Loader started (mode: " .. LOADER_MODE .. ")")
log("PlaceId: " .. game.PlaceId)
log("API: " .. API_URL)
startLoaderPresence()

if API_URL:find("YOUR_SUBDOMAIN", 1, true) then
    logError("Config", "Loader not configured")
    notify("KLZE HUB", "Loader not configured", 6)
    return
end

local function releaseLoaderBusy()
    if typeof(getgenv) == "function" then
        getgenv().__KLZE_LOADER_BUSY = nil
    end
end

if LOADER_MODE == "keyless" then
    log("Keyless hub - loading script (no key UI)")
    loadHubScript(noopGui())
    releaseLoaderBusy()
    log("Done. Log file: workspace/" .. LOG_FILE)
    return
end

local gui = createLoaderGui(false)
gui.setProgress(0.05)

