local userKey = authenticateWithJnkie(gui, Junkie)
if not userKey then
    logError("Jnkie", "No valid key")
    releaseLoaderBusy()
    return
end

if LOADER_MODE == "jnkie-ui" then
    log("jnkie-ui: key validated, SCRIPT_KEY set for Jnkie main script")
    gui.setStatus("Key valid!", Color3.fromRGB(120, 220, 160))
    task.delay(0.4, function()
        gui.close()
    end)
    releaseLoaderBusy()
    return
end

gui.setProgress(0.2)
loadHubScript(gui)
log("Done. Log file: workspace/" .. LOG_FILE)
releaseLoaderBusy()
